//! Snipdeck symbols library: emoji, kaomoji and icons. Pure Rust, no UI, no platform code.
//!
//! The data under `data/` is generated by `scripts/symbols.py` (see `docs/reviews/symbols-spec.md`)
//! and embedded with `include_bytes!`. Nothing is inflated or parsed until [`Catalog::get`] is first
//! called, so an app that never opens the Symbols tab pays nothing at start-up.
//!
//! - [`Catalog`]: every symbol, built once and lazily.
//! - [`search`]: ranked search over names and keywords in the UI language plus English.
//! - [`Recents`]: most recently used symbols, pure, with the clock passed in.
//! - [`ArtCache`] and [`Catalog::art`]: emoji art decoded and resampled to device pixels.
//! - [`Catalog::icon_svg`] and [`Catalog::icon_png`]: Phosphor icons as SVG text or a PNG render.
#![forbid(unsafe_code)]

mod art;
mod catalog;
mod data;
mod fold;
mod icon;
mod recents;
mod search;

pub use art::{ArtCache, ArtPack};
pub use catalog::{
    Catalog, EMOJI_GROUPS, KAOMOJI_GROUPS, Kind, Lang, Symbol, SymbolId, catalog_init_count,
};
pub use data::DataError;
pub use fold::fold;
pub use recents::{RECENTS_MAX, RecentEntry, Recents};
pub use search::{Hit, Rank, search};
